void keycat_render(void) {
    static uint32_t frame_timer;
    static uint8_t idle_frame;
    static uint8_t tap_frame;
    static bool drawn;
    if (drawn && timer_elapsed32(frame_timer) <= ANIM_FRAME_DURATION) {
        return;
    }
    drawn = true;
    frame_timer = timer_read32();
    const uint8_t wpm = get_current_wpm();
    const char *frame;
    if (wpm <= IDLE_SPEED) {
        idle_frame = (idle_frame + 1) % IDLE_FRAMES;
        frame = idle[IDLE_FRAMES - 1 - idle_frame];
    } else if (wpm < TAP_SPEED) {
        frame = prep[0];
    } else {
        tap_frame = (tap_frame + 1) % TAP_FRAMES;
        frame = tap[TAP_FRAMES - 1 - tap_frame];
    }
    oled_set_cursor(0, 0);
    oled_write_raw_P(frame, ANIM_SIZE);
}
